INSERT INTO ai_analysis (
    user_id, snapshot_id, simulation_id, analysis_type, result_json,
    input_data_hash, model_name, prompt_version
) VALUES (
    #{userId}, #{snapshotId}, #{simulationId}, #{analysisType}, #{resultJson},
    #{inputDataHash}, #{modelName}, #{promptVersion}
)

mapper.select:
SELECT 
FROM ai_analysis
WHERE analysis_id = #{analysisId}
  AND user_id = #{userId}

SELECT 
FROM ai_analysis
WHERE user_id = #{userId}
  AND input_data_hash = #{inputDataHash}
ORDER BY created_at DESC, analysis_id DESC
LIMIT 1

